}

function summarizeScanResult(scan: ScanResult | null) {
  if (!scan) return '';
  const libraryEntries = (Object.entries(scan.aiLibraryMatches ?? {}) as Array<[string, number]>).sort(
    (a, b) => b[1] - a[1]
  );
  const functionEntries = (Object.entries(scan.aiFunctionMatches ?? {}) as Array<[string, number]>).sort(
    (a, b) => b[1] - a[1]
  );
  const libraries = libraryEntries.slice(0, 5).map(([name, count]) => `${name} (${count})`).join(', ');
  const functions = functionEntries.slice(0, 5).map(([name, count]) => `${name} (${count})`).join(', ');

  return [
    `Detected ${scan.aiFiles.length} AI related files out of ${scan.totalFiles} scanned.`,
    libraries ? `Top libraries: ${libraries}` : 'No AI libraries detected.',
    functions ? `Top functions: ${functions}` : 'No AI-specific functions detected.'
  ].join('\n');
}

function runScanCommand({ root = process.cwd(), ci = false, json = false, silent = false }: ScanOptions) {
  const result = Scanners.scanCodebase({ root });

  if (json) {
    console.log(JSON.stringify(result, null, 2));
    return result;
  }

  if (!silent) {
    log.info('Scan completed.', {
      totalFiles: result.totalFiles,
      aiFiles: result.aiFiles.length
    });
    if (result.aiFiles.length) {
      console.log('AI-related files:');
      result.aiFiles.forEach((file) => console.log(`  - ${path.relative(root, file)}`));
    }
    if (!result.aiFiles.length) {
      log.info('No AI indicators detected in scope.');
    }
    if (ci) {
      log.info('CI mode: exiting after scan.');
    }
  }

  return result;
}

type FetchLike = (input: unknown, init?: unknown) => Promise<unknown>;

let cachedFetch: FetchLike | null = null;

async function resolveFetchImplementation(): Promise<FetchLike> {
  if (typeof (globalThis as { fetch?: FetchLike }).fetch === 'function') {
    return (globalThis as { fetch: FetchLike }).fetch.bind(globalThis);
  }
  if (cachedFetch) return cachedFetch;
  const mod = await import('node-fetch');
  cachedFetch = (mod.default ?? mod) as FetchLike;
  return cachedFetch;
}

async function generateAITips(answers: Awaited<ReturnType<typeof Questionnaire.runQuestionnaire>>, apiKey: string | null, scan: ScanResult | null) {
